CREATE FUNCTION guard_review() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.status IN ('COMPLETE', 'PARTIAL', 'FAILED', 'CANCELLED')
    AND NEW.status IS DISTINCT FROM OLD.status THEN
  RAISE EXCEPTION 'a terminal review keeps its status' USING ERRCODE = '55000';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER review_transition BEFORE UPDATE OF status ON review FOR EACH ROW EXECUTE FUNCTION guard_review();
